{
  "cards": {
    "cover": {
      "narration": "Not my island, but I’ve done my homework. Reykjavik, 8–12 Feb 2027, 5 days, 3 travellers.",
      "headline": "Reykjavik"
    },
    "critters": {
      "narration": "Zero forms found, zero new locals. Tokek thinks the good hiding spots won this round."
    },
    "route": {
      "narration": "Reykjavik, Thingvellir, Vik, Jökulsárlón. About 402.6 km of road, with the longest hop from Vik to Jökulsárlón.",
      "line": "The longest leg was about 189.3 km from Vik to Jökulsárlón in 150 minutes, and no driver was logged."
    },
    "awards": {
      "narration": "Three travellers, three little awards from Tokek's shelf. Here they come."
    },
    "receipt": {
      "narration": "The kitty: ISK 612,000 total, ISK 204,000 each. No plan was set, but everything settled 4 days after the trip.",
      "line": "26 expenses, 14 meals, all square."
    },
    "stamp": {
      "narration": "The passport stamp goes thunk: 5 days, 3 travellers, one very tidy little trip."
    },
    "postcard": {
      "narration": "Tokek signs the postcard, and here is the note home.",
      "line": "Reykjavik, 8–12 Feb 2027. About 402.6 km, zero critters, all settled in 4 days. Wish you were here."
    }
  },
  "awards": [
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000001",
      "title": "Navigator of all rides",
      "line": "Logged 4 of 4 rides, every single one."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000002",
      "title": "Treasurer's steady hand",
      "line": "Logged 12 of 26 expenses, a cool 46 percent."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000003",
      "title": "Planner in chief",
      "line": "Made 3 of 3 plan edits, all of them."
    }
  ]
}
